import fs from 'fs';import path from 'path';const root='sep18-sg-sidebar-combined',rows=[];function walk(d){if(!fs.existsSync(d))return;for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);if(e.isDirectory())walk(p);else if(e.name==='result.json')try{rows.push(JSON.parse(fs.readFileSync(p,'utf8')))}catch{}}}walk(root);const bad=rows.filter(r=>r.httpStatus!==200||!r.previewOk||r.error||(r.sidebarApplicable!==false&&!r.triggerVisible)||r.invalidHrefs?.length||r.brokenImages);const empty=rows.filter(r=>r.sidebarApplicable!==false&&r.categoryCount===0);const summary={generatedAt:new Date().toISOString(),total:rows.length,sidebarApplicable:rows.filter(r=>r.sidebarApplicable!==false).length,sidebarNotApplicable:rows.filter(r=>r.sidebarApplicable===false).map(r=>({label:r.label,route:r.route})),passed:rows.length-bad.length,failed:bad.length,emptyCategories:empty.map(x=>({label:x.label,route:x.route})),totalCategories:rows.reduce((s,x)=>s+(x.categoryCount||0),0),totalSubcategories:rows.reduce((s,x)=>s+(x.subcategoryCount||0),0),totalTypes:rows.reduce((s,x)=>s+(x.typeCount||0),0),averageLoadMs:rows.length?Math.round(rows.reduce((s,x)=>s+(x.loadMs||0),0)/rows.length):0,failures:bad.map(x=>({label:x.label,route:x.route,http:x.httpStatus,error:x.error,previewOk:x.previewOk,triggerVisible:x.triggerVisible,invalidHrefs:x.invalidHrefs?.length,brokenImages:x.brokenImages})),rows};fs.mkdirSync('sep18-sg-sidebar-final',{recursive:true});fs.writeFileSync('sep18-sg-sidebar-final/summary.json',JSON.stringify(summary,null,2));console.log('SGSIDEBARSUMMARY',JSON.stringify({...summary,rows:undefined}));if(bad.length)process.exitCode=2;